        exercise: "# Objectif: statistiques pour data science\n\nimport numpy as np\nfrom scipy import stats\nimport matplotlib.pyplot as plt\n\n# 1. Mesures de tendance centrale\ndata = np.random.normal(50, 10, 1000)\n\nmean = np.mean(data)         # moyenne\nmedian = np.median(data)     # médiane (robuste outliers)\nmode = stats.mode(data, keepdims=False)\n\n# 2. Mesures de dispersion\nstd = np.std(data, ddof=1)   # écart-type (sample)\nvar = np.var(data, ddof=1)\niqr = np.percentile(data, 75) - np.percentile(data, 25)   # robuste\nrange_ = np.max(data) - np.min(data)\n\n# 3. Distribution\n# Normal (gaussienne)\nstats.norm.pdf(0, loc=0, scale=1)        # PDF\nstats.norm.cdf(1.96, loc=0, scale=1)     # P(X<=1.96) ≈ 0.975\nstats.norm.ppf(0.975, loc=0, scale=1)    # quantile inverse ≈ 1.96\n\n# Test de normalité\nstat, p = stats.shapiro(data)\nis_normal = p > 0.05\n\n# 4. Z-score (standardisation)\nz = (data - mean) / std\n# |z| > 3 → outlier (3-sigma rule)\noutliers = data[np.abs(z) > 3]\n\n# 5. Intervalle de confiance\n# 95% CI pour la moyenne\nci_low, ci_high = stats.t.interval(\n    confidence=0.95,\n    df=len(data) - 1,\n    loc=mean,\n    scale=stats.sem(data)\n)\nprint(f'95% CI: [{ci_low:.2f}, {ci_high:.2f}]')\n\n# 6. Hypothesis testing\n\n# t-test (comparer 2 groupes)\ngroup_a = np.random.normal(50, 10, 100)\ngroup_b = np.random.normal(55, 10, 100)\nt_stat, p_value = stats.ttest_ind(group_a, group_b)\n# p_value < 0.05 → différence significative\n\n# Chi-square (variables catégorielles)\nobserved = np.array([[10, 20, 30], [20, 30, 50]])\nchi2, p, dof, expected = stats.chi2_contingency(observed)\n\n# ANOVA (>2 groupes)\nf_stat, p = stats.f_oneway(group_a, group_b, group_c)\n\n# 7. Corrélation\nx = np.random.normal(0, 1, 100)\ny = 2 * x + np.random.normal(0, 0.5, 100)\n\n# Pearson (linéaire, suppose normalité)\nr, p = stats.pearsonr(x, y)\n\n# Spearman (rank-based, non-linéaire)\nrho, p = stats.spearmanr(x, y)\n\n# 8. Bootstrap (intervalle de confiance robuste)\ndef bootstrap_ci(data, stat_fn, n_iter=10000, alpha=0.05):\n    stats_arr = []\n    for _ in range(n_iter):\n        sample = np.random.choice(data, size=len(data), replace=True)\n        stats_arr.append(stat_fn(sample))\n    return np.percentile(stats_arr, [100*alpha/2, 100*(1-alpha/2)])\n\nci = bootstrap_ci(data, np.mean)\n\n# 9. A/B testing pratique\n# Conversion control: 100/1000 = 10%\n# Conversion variant: 130/1000 = 13%\n# Significant ?\nfrom statsmodels.stats.proportion import proportions_ztest\nstat, p = proportions_ztest([100, 130], [1000, 1000])\nif p < 0.05:\n    print(f'Significant lift: {(130/1000 - 100/1000)/(100/1000)*100:.1f}%')\n\n# 10. Power analysis (combien de samples nécessaires?)\nfrom statsmodels.stats.power import TTestIndPower\nanalysis = TTestIndPower()\nn = analysis.solve_power(\n    effect_size=0.5,   # Cohen's d (small=0.2, medium=0.5, large=0.8)\n    alpha=0.05,\n    power=0.8\n)\nprint(f'Need {n:.0f} samples per group')\n\n# 11. Distribution sampling\nimport pandas as pd\n\n# Stratified sample (proportional par catégorie)\ndf = pd.read_csv('data.csv')\nsample = df.groupby('category', group_keys=False).apply(\n    lambda x: x.sample(frac=0.1, random_state=42)\n)\n\n# 12. Use cases data engineering\n# - Anomaly detection (Z-score)\n# - Validation pipelines (test if dist drift)\n# - A/B testing analysis\n# - Capacity planning (intervalles confiance)",
