        exercise: "# Objectif: gradient descent from scratch\n\nimport numpy as np\nimport matplotlib.pyplot as plt\n\n# 1. Concept: minimiser f(x) = (x-3)²\n# Solution analytique: x = 3 (dérivée = 0)\n\n# Avec gradient descent:\nx = 0.0   # init random\nlr = 0.1  # learning rate\nhistory = []\n\nfor i in range(100):\n    grad = 2 * (x - 3)   # dérivée\n    x = x - lr * grad\n    history.append(x)\n\nplt.plot(history)\nplt.axhline(y=3, color='r', linestyle='--')\nplt.title('Gradient Descent Convergence')\n# Converge vers 3\n\n# 2. Régression linéaire from scratch\n# y = w*x + b\n\ndef linear_regression(X, y, lr=0.01, epochs=1000):\n    n_features = X.shape[1]\n    w = np.zeros(n_features)\n    b = 0\n    losses = []\n    \n    for epoch in range(epochs):\n        # Forward pass\n        y_pred = X @ w + b\n        \n        # Loss (MSE)\n        loss = ((y_pred - y) ** 2).mean()\n        losses.append(loss)\n        \n        # Backward (gradients)\n        grad_w = 2 * X.T @ (y_pred - y) / len(y)\n        grad_b = 2 * (y_pred - y).mean()\n        \n        # Update\n        w -= lr * grad_w\n        b -= lr * grad_b\n    \n    return w, b, losses\n\n# Test\nnp.random.seed(42)\nX = np.random.randn(100, 3)\ntrue_w = np.array([1.5, -2.0, 0.5])\ny = X @ true_w + 0.5 + 0.1 * np.random.randn(100)\n\nw, b, losses = linear_regression(X, y, lr=0.05, epochs=500)\nprint(f'w: {w}, b: {b}')\nprint(f'True: w={true_w}, b=0.5')\n\n# 3. Learning rate impact\nfor lr in [0.001, 0.01, 0.1, 1.0]:\n    _, _, losses = linear_regression(X, y, lr=lr, epochs=100)\n    plt.plot(losses, label=f'lr={lr}')\nplt.legend(); plt.yscale('log')\n# Trop petit: lent\n# Trop grand: oscille / diverge\n# Sweet spot = optimal\n\n# 4. Variantes Gradient Descent\n\n# A. Batch GD: tout dataset\n# B. Stochastic GD: 1 sample (bruyant mais rapide)\n# C. Mini-batch GD: 32-256 samples (standard ML)\n\ndef sgd(X, y, lr=0.01, epochs=10, batch_size=32):\n    w = np.zeros(X.shape[1])\n    b = 0\n    n = len(y)\n    \n    for epoch in range(epochs):\n        idx = np.random.permutation(n)\n        for i in range(0, n, batch_size):\n            batch_idx = idx[i:i+batch_size]\n            X_b, y_b = X[batch_idx], y[batch_idx]\n            \n            y_pred = X_b @ w + b\n            grad_w = 2 * X_b.T @ (y_pred - y_b) / len(y_b)\n            grad_b = 2 * (y_pred - y_b).mean()\n            \n            w -= lr * grad_w\n            b -= lr * grad_b\n    \n    return w, b\n\n# 5. Optimizers avancés (utilisés en DL)\n\n# Momentum: garde mémoire du gradient précédent\n# v = β*v + (1-β)*grad\n# w = w - lr*v\n# β = 0.9 typique\n\n# Adam: combine momentum + learning rate adaptatif\n# Le default de tout DL\n\n# 6. PyTorch autograd (automatique)\nimport torch\n\n# Define\nx = torch.tensor(0.0, requires_grad=True)\n\n# Optimizer\noptimizer = torch.optim.Adam([x], lr=0.1)\n\n# Loss function\ndef loss_fn(x):\n    return (x - 3) ** 2\n\n# Training loop\nfor i in range(100):\n    optimizer.zero_grad()\n    loss = loss_fn(x)\n    loss.backward()        # auto compute gradients\n    optimizer.step()        # update params\n\nprint(x.item())   # ≈ 3.0\n\n# 7. Visualizing loss landscape\n# Create grid\nw1 = np.linspace(-5, 5, 100)\nw2 = np.linspace(-5, 5, 100)\nW1, W2 = np.meshgrid(w1, w2)\n\n# Compute loss at each point\nLoss = np.zeros_like(W1)\nfor i in range(W1.shape[0]):\n    for j in range(W1.shape[1]):\n        w = np.array([W1[i,j], W2[i,j], 0])   # 3rd dim fixed\n        Loss[i,j] = ((X @ w - y) ** 2).mean()\n\n# Contour plot\nplt.contour(W1, W2, Loss, levels=20)\nplt.colorbar()\n# Trajectoire gradient descent superposée\n\n# 8. Common issues\n# - Vanishing gradient (deep networks)\n# - Exploding gradient (gradient clipping)\n# - Local minima (momentum aide)\n# - Saddle points (Adam aide)\n# - Overfitting (regularization, dropout)\n\n# Tips pratiques:\n# - lr_init = 1e-3 pour Adam (défaut)\n# - lr_init = 1e-4 pour fine-tuning\n# - lr_scheduler: ReduceLROnPlateau\n# - Early stopping si val_loss stagnant\n# - Batch normalization (stabilise)",
