        exercise: "# Objectif: clustering + dim reduction\n\nimport numpy as np\nfrom sklearn.cluster import KMeans, DBSCAN, AgglomerativeClustering\nfrom sklearn.decomposition import PCA\nfrom sklearn.manifold import TSNE\nimport umap\nfrom sklearn.preprocessing import StandardScaler\nimport matplotlib.pyplot as plt\n\n# 1. KMeans (clusters fixes)\nfrom sklearn.datasets import make_blobs\nX, _ = make_blobs(n_samples=300, centers=4, random_state=42)\n\nkmeans = KMeans(n_clusters=4, n_init=10, random_state=42)\nlabels = kmeans.fit_predict(X)\ncenters = kmeans.cluster_centers_\n\nplt.scatter(X[:, 0], X[:, 1], c=labels, cmap='tab10')\nplt.scatter(centers[:, 0], centers[:, 1], s=200, marker='X', c='red')\n\n# Choisir k: elbow method\ninertias = []\nfor k in range(1, 11):\n    km = KMeans(n_clusters=k, n_init=10).fit(X)\n    inertias.append(km.inertia_)\nplt.plot(range(1, 11), inertias)\n# 'Coude' = bon k\n\n# Silhouette score (mesure qualité)\nfrom sklearn.metrics import silhouette_score\nfor k in [2, 3, 4, 5]:\n    km = KMeans(n_clusters=k).fit(X)\n    score = silhouette_score(X, km.labels_)\n    print(f'k={k}: silhouette={score:.3f}')\n\n# 2. DBSCAN (densité, sans k)\ndb = DBSCAN(eps=0.3, min_samples=10)\nlabels = db.fit_predict(X)\nn_clusters = len(set(labels)) - (1 if -1 in labels else 0)\nn_noise = (labels == -1).sum()\n\n# DBSCAN détecte clusters de forme arbitraire + outliers\n\n# 3. Hierarchical clustering\nagg = AgglomerativeClustering(n_clusters=4)\nlabels = agg.fit_predict(X)\n\n# Dendrogramme\nfrom scipy.cluster.hierarchy import dendrogram, linkage\nlinkage_matrix = linkage(X, method='ward')\ndendrogram(linkage_matrix)\n\n# 4. PCA (réduction dimension linéaire)\nfrom sklearn.datasets import load_iris\niris = load_iris()\nX, y = iris.data, iris.target\n\n# Toujours scaler avant PCA\nX_scaled = StandardScaler().fit_transform(X)\n\npca = PCA(n_components=2)\nX_pca = pca.fit_transform(X_scaled)\n\nplt.scatter(X_pca[:, 0], X_pca[:, 1], c=y)\nplt.xlabel(f'PC1 ({pca.explained_variance_ratio_[0]:.1%})')\nplt.ylabel(f'PC2 ({pca.explained_variance_ratio_[1]:.1%})')\n\n# Combien de composantes garder?\npca_full = PCA().fit(X_scaled)\ncumvar = pca_full.explained_variance_ratio_.cumsum()\nplt.plot(cumvar)\n# Garder N tel que cumvar > 0.95\n\n# 5. t-SNE (non-linear, pour visualisation)\ntsne = TSNE(n_components=2, perplexity=30, random_state=42)\nX_tsne = tsne.fit_transform(X_scaled)\n# Slow sur > 10k samples\n\n# 6. UMAP (meilleur que t-SNE)\nreducer = umap.UMAP(n_neighbors=15, min_dist=0.1, n_components=2)\nX_umap = reducer.fit_transform(X_scaled)\n# Plus rapide + préserve mieux structure globale\n\n# 7. Cas pratique GPS:\n# Trouver hubs urbains automatiquement\n\nimport pandas as pd\ndf = pd.read_csv('gps_origins.csv')\ncoords = df[['lat','lon']].values\n\n# DBSCAN avec haversine\ncoords_rad = np.radians(coords)\ndb = DBSCAN(eps=0.5/6371, min_samples=10, metric='haversine').fit(coords_rad)\ndf['cluster'] = db.labels_\n\nhubs = df[df.cluster != -1].groupby('cluster').agg({\n    'lat':'mean', 'lon':'mean', 'cluster':'size'\n})\n# = hubs automatiques + outliers\n\n# 8. Anomaly detection (Isolation Forest)\nfrom sklearn.ensemble import IsolationForest\n\niso = IsolationForest(contamination=0.05, random_state=42)\nanomalies = iso.fit_predict(X)\n# -1 = anomalie, 1 = normal\n\n# 9. Use cases\n# - Customer segmentation (KMeans sur transactions)\n# - Anomaly detection (Isolation Forest)\n# - Document clustering (TF-IDF + KMeans)\n# - Image dimensionality (PCA before NN)\n# - Visualization 2D (UMAP)",
