        exercise: "# Objectif: PyTorch fondamentaux\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom torch.utils.data import DataLoader, TensorDataset, random_split\n\n# 1. Tensors (NumPy++)\nx = torch.tensor([1.0, 2.0, 3.0])\nx = torch.zeros(3, 4)\nx = torch.randn(2, 3)\nx = torch.from_numpy(np_array)\nx_np = x.numpy()\n\n# Device (GPU)\ndevice = torch.device('cuda' if torch.cuda.is_available() else 'cpu')\nx = x.to(device)\n\n# 2. Autograd (différentiation auto)\nx = torch.tensor(2.0, requires_grad=True)\ny = x**2 + 3*x + 1\ny.backward()\nprint(x.grad)   # dy/dx = 2x + 3 = 7\n\n# 3. nn.Module (pattern modèle)\nclass MLP(nn.Module):\n    def __init__(self, input_dim, hidden_dim, output_dim):\n        super().__init__()\n        self.fc1 = nn.Linear(input_dim, hidden_dim)\n        self.fc2 = nn.Linear(hidden_dim, hidden_dim)\n        self.fc3 = nn.Linear(hidden_dim, output_dim)\n        self.dropout = nn.Dropout(0.3)\n    \n    def forward(self, x):\n        x = F.relu(self.fc1(x))\n        x = self.dropout(x)\n        x = F.relu(self.fc2(x))\n        return self.fc3(x)\n\nmodel = MLP(10, 64, 1).to(device)\n\n# Voir paramètres\nfor name, param in model.named_parameters():\n    print(name, param.shape, param.numel())\n\nn_params = sum(p.numel() for p in model.parameters())\nprint(f'Total: {n_params:,} parameters')\n\n# 4. Dataset & DataLoader\nclass TripsDataset(torch.utils.data.Dataset):\n    def __init__(self, X, y):\n        self.X = torch.tensor(X.values, dtype=torch.float32)\n        self.y = torch.tensor(y.values, dtype=torch.float32)\n    \n    def __len__(self):\n        return len(self.y)\n    \n    def __getitem__(self, idx):\n        return self.X[idx], self.y[idx]\n\nds = TripsDataset(X_train, y_train)\nloader = DataLoader(ds, batch_size=32, shuffle=True, num_workers=4)\n\n# 5. Training loop standard\noptimizer = torch.optim.Adam(model.parameters(), lr=1e-3)\nloss_fn = nn.MSELoss()\nscheduler = torch.optim.lr_scheduler.ReduceLROnPlateau(optimizer, mode='min', patience=3)\n\nfor epoch in range(50):\n    # Train\n    model.train()\n    train_loss = 0\n    for X_batch, y_batch in train_loader:\n        X_batch, y_batch = X_batch.to(device), y_batch.to(device)\n        \n        pred = model(X_batch)\n        loss = loss_fn(pred.squeeze(), y_batch)\n        \n        optimizer.zero_grad()\n        loss.backward()\n        # Gradient clipping (évite exploding gradients)\n        torch.nn.utils.clip_grad_norm_(model.parameters(), max_norm=1.0)\n        optimizer.step()\n        \n        train_loss += loss.item()\n    \n    # Validation\n    model.eval()\n    val_loss = 0\n    with torch.no_grad():\n        for X_batch, y_batch in val_loader:\n            X_batch, y_batch = X_batch.to(device), y_batch.to(device)\n            pred = model(X_batch)\n            val_loss += loss_fn(pred.squeeze(), y_batch).item()\n    \n    scheduler.step(val_loss)\n    print(f'Epoch {epoch}: train={train_loss/len(train_loader):.4f}, val={val_loss/len(val_loader):.4f}')\n\n# 6. Save & load\ntorch.save(model.state_dict(), 'model.pt')\nmodel.load_state_dict(torch.load('model.pt'))\nmodel.eval()\n\n# 7. Inference\nmodel.eval()\nwith torch.no_grad():\n    X_test_t = torch.tensor(X_test.values, dtype=torch.float32).to(device)\n    pred = model(X_test_t).cpu().numpy()\n\n# 8. Pattern PyTorch Lightning (production)\n# Réduit boilerplate, adds best practices\nimport lightning as L\n\nclass LitModel(L.LightningModule):\n    def __init__(self, model, lr=1e-3):\n        super().__init__()\n        self.model = model\n        self.lr = lr\n    \n    def training_step(self, batch, batch_idx):\n        x, y = batch\n        pred = self.model(x)\n        loss = F.mse_loss(pred.squeeze(), y)\n        self.log('train_loss', loss)\n        return loss\n    \n    def validation_step(self, batch, batch_idx):\n        x, y = batch\n        pred = self.model(x)\n        loss = F.mse_loss(pred.squeeze(), y)\n        self.log('val_loss', loss)\n    \n    def configure_optimizers(self):\n        return torch.optim.Adam(self.parameters(), lr=self.lr)\n\ntrainer = L.Trainer(max_epochs=50, accelerator='auto')\ntrainer.fit(LitModel(model), train_loader, val_loader)\n\n# 9. Outils écosystème\n# - Hugging Face Transformers (NLP)\n# - Pytorch Lightning (production)\n# - Weights & Biases (experiments tracking)\n# - TorchServe (model serving)\n# - ONNX (export pour C++/JS deploy)",
