        exercise: "# Objectif: classifier images avec CNN pré-entraîné\n\nimport torch\nimport torch.nn as nn\nimport torchvision\nimport torchvision.transforms as T\nfrom torch.utils.data import DataLoader\n\ndevice = 'cuda' if torch.cuda.is_available() else 'cpu'\n\n# 1. Transforms (preprocessing images)\ntransform = T.Compose([\n    T.Resize(256),\n    T.CenterCrop(224),\n    T.ToTensor(),\n    T.Normalize(mean=[0.485, 0.456, 0.406],   # ImageNet stats\n                std=[0.229, 0.224, 0.225])\n])\n\n# 2. Load dataset\ntrain_data = torchvision.datasets.ImageFolder('data/train', transform=transform)\nval_data = torchvision.datasets.ImageFolder('data/val', transform=transform)\n\ntrain_loader = DataLoader(train_data, batch_size=32, shuffle=True, num_workers=4)\nval_loader = DataLoader(val_data, batch_size=32, num_workers=4)\n\nn_classes = len(train_data.classes)\n\n# 3. Modèle pré-entraîné ResNet50\nfrom torchvision.models import resnet50, ResNet50_Weights\n\nmodel = resnet50(weights=ResNet50_Weights.IMAGENET1K_V2)\n# Pré-entraîné sur 1.4M images ImageNet\n\n# Freeze all (sauf dernière couche)\nfor param in model.parameters():\n    param.requires_grad = False\n\n# Replace final layer (transfer learning)\nmodel.fc = nn.Sequential(\n    nn.Dropout(0.3),\n    nn.Linear(model.fc.in_features, 256),\n    nn.ReLU(),\n    nn.Dropout(0.3),\n    nn.Linear(256, n_classes)\n)\n\nmodel = model.to(device)\n\n# 4. Training (que les params unfrozen)\noptimizer = torch.optim.Adam(\n    [p for p in model.parameters() if p.requires_grad],\n    lr=1e-3\n)\nloss_fn = nn.CrossEntropyLoss()\nscheduler = torch.optim.lr_scheduler.CosineAnnealingLR(optimizer, T_max=10)\n\nfor epoch in range(10):\n    # Training\n    model.train()\n    correct, total, loss_sum = 0, 0, 0\n    for X, y in train_loader:\n        X, y = X.to(device), y.to(device)\n        pred = model(X)\n        loss = loss_fn(pred, y)\n        \n        optimizer.zero_grad()\n        loss.backward()\n        optimizer.step()\n        \n        loss_sum += loss.item()\n        correct += (pred.argmax(1) == y).sum().item()\n        total += y.size(0)\n    \n    train_acc = correct / total\n    \n    # Validation\n    model.eval()\n    correct, total = 0, 0\n    with torch.no_grad():\n        for X, y in val_loader:\n            X, y = X.to(device), y.to(device)\n            pred = model(X)\n            correct += (pred.argmax(1) == y).sum().item()\n            total += y.size(0)\n    val_acc = correct / total\n    \n    scheduler.step()\n    print(f'Epoch {epoch}: train_acc={train_acc:.3f}, val_acc={val_acc:.3f}')\n\n# 5. Fine-tuning (dégeler couches après convergence base)\nfor param in model.parameters():\n    param.requires_grad = True\n\noptimizer = torch.optim.Adam(model.parameters(), lr=1e-5)   # lr plus petit\n# Re-train quelques epochs\n\n# 6. Inference sur 1 image\nfrom PIL import Image\n\nimg = Image.open('test.jpg')\nx = transform(img).unsqueeze(0).to(device)\n\nmodel.eval()\nwith torch.no_grad():\n    logits = model(x)\n    probs = torch.softmax(logits, dim=1)\n    pred_class = probs.argmax(dim=1).item()\n    confidence = probs[0, pred_class].item()\n\nclass_name = train_data.classes[pred_class]\nprint(f'{class_name}: {confidence:.2%}')\n\n# 7. Visualiser activations (Grad-CAM)\n# pip install grad-cam\nfrom pytorch_grad_cam import GradCAM\nfrom pytorch_grad_cam.utils.image import show_cam_on_image\n\ncam = GradCAM(model=model, target_layers=[model.layer4[-1]])\ngrayscale_cam = cam(input_tensor=x)\n# Heatmap montre quelles parties de l'image décident\n\n# 8. Architectures modernes\nfrom timm import create_model\n\n# Compare facilement modèles\nmodel = create_model('efficientnet_b3', pretrained=True, num_classes=n_classes)\nmodel = create_model('vit_base_patch16_224', pretrained=True, num_classes=n_classes)\nmodel = create_model('convnext_base', pretrained=True, num_classes=n_classes)\n\n# 9. Use cases business\n# - Detection défauts produits (manufacturing)\n# - Reconnaissance documents (KYC)\n# - Médical: classification radiographies\n# - Mobilité: signalisation routière\n# - Retail: reconnaissance produits\n\n# Applicable à laverie:\n# - Reconnaissance véhicule depuis caméra\n# - Détection problèmes (état véhicule)\n# - Counting (combien de gens dans laverie)",
