        exercise: "# Objectif: ML en production\n\n# 1. MLflow Tracking\nimport mlflow\nimport mlflow.sklearn\n\nmlflow.set_tracking_uri('http://localhost:5000')\nmlflow.set_experiment('trip_duration_predictor')\n\nwith mlflow.start_run(run_name='xgb_v3'):\n    # Log params\n    params = {'n_estimators':200, 'max_depth':6, 'lr':0.1}\n    mlflow.log_params(params)\n    \n    # Train\n    model = XGBRegressor(**params)\n    model.fit(X_train, y_train)\n    \n    # Eval\n    pred = model.predict(X_test)\n    mae = mean_absolute_error(y_test, pred)\n    r2 = r2_score(y_test, pred)\n    \n    # Log metrics\n    mlflow.log_metric('mae', mae)\n    mlflow.log_metric('r2', r2)\n    \n    # Log artifacts\n    mlflow.log_artifact('plots/feature_importance.png')\n    \n    # Log model (auto serializable)\n    mlflow.sklearn.log_model(\n        model, \n        'model',\n        registered_model_name='trip_duration_v1',\n        signature=mlflow.models.signature.infer_signature(X_train, pred)\n    )\n\n# UI: mlflow ui --port 5000\n# Compare runs, voir métriques, télécharger models\n\n# 2. Model Registry (versioning)\nclient = mlflow.MlflowClient()\nclient.transition_model_version_stage(\n    name='trip_duration_v1',\n    version=3,\n    stage='Production'   # ou Staging, Archived\n)\n\n# Load production model\nmodel = mlflow.pyfunc.load_model('models:/trip_duration_v1/Production')\npred = model.predict(X)\n\n# 3. FastAPI serving\n# api.py\nfrom fastapi import FastAPI, HTTPException\nfrom pydantic import BaseModel, Field\nimport mlflow.pyfunc\nimport pandas as pd\nimport time\nimport logging\n\napp = FastAPI(title='Trip Duration Predictor')\nlog = logging.getLogger(__name__)\n\n# Load model at startup\n@app.on_event('startup')\ndef load_model():\n    global model\n    model = mlflow.pyfunc.load_model('models:/trip_duration_v1/Production')\n    log.info('Model loaded')\n\nclass TripFeatures(BaseModel):\n    distance_km: float = Field(gt=0, le=10000)\n    hour: int = Field(ge=0, le=23)\n    weekday: int = Field(ge=0, le=6)\n    temperature: float\n    \n    class Config:\n        json_schema_extra = {\n            'example': {\n                'distance_km': 5.5,\n                'hour': 14,\n                'weekday': 1,\n                'temperature': 22.5\n            }\n        }\n\n@app.post('/predict')\ndef predict(features: TripFeatures):\n    start = time.time()\n    \n    df = pd.DataFrame([features.dict()])\n    pred = model.predict(df)[0]\n    \n    duration_ms = (time.time() - start) * 1000\n    \n    # Log pour monitoring\n    log.info({\n        'event': 'prediction',\n        'features': features.dict(),\n        'prediction': float(pred),\n        'duration_ms': duration_ms\n    })\n    \n    return {\n        'predicted_duration_min': float(pred),\n        'inference_time_ms': duration_ms\n    }\n\n@app.get('/health')\ndef health():\n    return {'status': 'ok', 'model_version': 'production'}\n\n# Run: uvicorn api:app --host 0.0.0.0 --port 8000\n\n# 4. Docker\n# Dockerfile:\n# FROM python:3.11-slim\n# WORKDIR /app\n# COPY requirements.txt .\n# RUN pip install --no-cache-dir -r requirements.txt\n# COPY . .\n# CMD [\"uvicorn\", \"api:app\", \"--host\", \"0.0.0.0\", \"--port\", \"8000\"]\n\n# 5. docker-compose.yml (full stack)\n# version: '3.8'\n# services:\n#   mlflow:\n#     image: ghcr.io/mlflow/mlflow:latest\n#     ports: ['5000:5000']\n#     volumes: ['./mlruns:/mlruns']\n#     command: mlflow server --host 0.0.0.0 --backend-store-uri sqlite:///mlruns.db\n#   api:\n#     build: .\n#     ports: ['8000:8000']\n#     environment:\n#       MLFLOW_TRACKING_URI: http://mlflow:5000\n#     depends_on: [mlflow]\n\n# 6. Tests\n# tests/test_api.py\nfrom fastapi.testclient import TestClient\nfrom api import app\n\nclient = TestClient(app)\n\ndef test_health():\n    r = client.get('/health')\n    assert r.status_code == 200\n\ndef test_predict():\n    r = client.post('/predict', json={\n        'distance_km': 5.5, 'hour': 14, 'weekday': 1, 'temperature': 22.5\n    })\n    assert r.status_code == 200\n    assert 'predicted_duration_min' in r.json()\n\ndef test_invalid_input():\n    r = client.post('/predict', json={'distance_km': -5, 'hour':0, 'weekday':0, 'temperature':20})\n    assert r.status_code == 422   # Pydantic validation error\n\n# 7. Monitoring drift (production)\n# - Log toutes les predictions + features\n# - Compare distribution actuel vs training\n# - Outils: Evidently AI, Whylogs, Arize\n\nfrom evidently.report import Report\nfrom evidently.metric_preset import DataDriftPreset\n\nreport = Report(metrics=[DataDriftPreset()])\nreport.run(reference_data=X_train, current_data=X_recent_predictions)\nreport.save_html('drift_report.html')\n\n# 8. Continuous training pipeline (CT)\n# Si drift détecté → re-train auto\n# Airflow DAG:\n# - Detect drift quotidien\n# - Si drift > threshold:\n#   - Re-train sur fresh data\n#   - Compare metrics vs production\n#   - Si meilleur: promote to production\n\n# 9. Outils MLOps écosystème\n# Tracking: MLflow, Weights & Biases, Neptune\n# Serving: TorchServe, Triton, BentoML, KServe\n# Pipelines: Kubeflow, Metaflow, Flyte\n# Monitoring: Evidently, Arize, Whylabs\n# Feature stores: Feast, Tecton\n# All-in-one: Vertex AI, Azure ML, SageMaker\n\n# 10. Pattern complet (CV)\n# 1. Data + features → MLflow tracking\n# 2. Best model → MLflow Registry\n# 3. CI/CD: tests + deploy si nouveau better\n# 4. FastAPI + Docker → K8s\n# 5. Monitoring drift + alerts\n# 6. Auto re-train pipeline (Airflow)\n# 7. A/B testing nouveau vs prod",
